/* Generates the widget files that must never be hand-edited (roadmap 2.1, 2.2).
 *
 *   node tools/widget_gen.js           write every generated file
 *   node tools/widget_gen.js --check   exit 1, naming each path that differs from what would be written
 *
 * generate(root) -> { [relPath]: text }. Output is byte-stable: sorted keys, no dates.
 * Today: workers/shared/widget-rules.mjs, app/since-rules.js, the native Swift, Kotlin and Android strings files
 * and docs/widgets/widget-fixtures.json (the reference
 * model's output over widget-copy.json's cases, in UTC). Later tasks extend the map. */
'use strict';
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const crypto = require('crypto');
const { createModel } = require('./widget_model');

function sortKeys(v) {
  if (Array.isArray(v)) return v.map(sortKeys);
  if (v && typeof v === 'object') { const o = {}; Object.keys(v).sort().forEach((k) => { o[k] = sortKeys(v[k]); }); return o; }
  return v;
}
const lit = (v) => JSON.stringify(sortKeys(v), null, 2);

const FN_NAMES = ['sinceAnchor', 'babyAnchors', 'healthOpen', 'isTwins', 'ageOf', 'monthMoments', 'sleepEventId', 'snapshotBaby'];

function generate(root) {
  const copy = JSON.parse(fs.readFileSync(path.join(root, 'docs/widgets/widget-copy.json'), 'utf8'));
  const body = fs.readFileSync(path.join(root, 'workers/shared/since-rules.mjs'), 'utf8');
  const consts = { RULES: copy.rules, DEFAULTS: copy.defaults, SNAPSHOT_VERSIONS: copy.snapshot.versions };

  const rulesMjs = '// GENERATED by tools/widget_gen.js from docs/widgets/widget-copy.json. Do not edit.\n'
    + Object.keys(consts).map((k) => 'export const ' + k + ' = ' + lit(consts[k]) + ';\n').join('');

  const moduleBody = body
    .replace(/^import .*\n/m, '')
    .replace(/^export \{[^}]*\};?\n/m, '')
    .replace(/^export (function|const|let)/gm, '$1')
    .replace(/^\n+/, '');
  // Guard 1: any `export` the strip did not understand (export async function, export class, export default)
  // would ship a syntax error inside the browser IIFE, so refuse rather than emit it.
  const leftover = moduleBody.split('\n').find((l) => /^\s*export\b/.test(l));
  if (leftover) throw new Error('since-rules.mjs has an export the generator cannot strip: ' + leftover.trim());
  // Guard 2: FN_NAMES is what window.CubbySince exposes; it must be exactly the module's own exported functions.
  const realFns = (body.match(/^export (?:function|const|let) +[A-Za-z_$][\w$]*/gm) || []).map((l) => l.split(/\s+/).pop()).sort();
  if (JSON.stringify(realFns) !== JSON.stringify(FN_NAMES.slice().sort())) {
    throw new Error('FN_NAMES differs from the exports of since-rules.mjs: module has [' + realFns.join(', ') + '], FN_NAMES has [' + FN_NAMES.slice().sort().join(', ') + ']');
  }
  const appStrings = {};
  Object.keys(copy.strings || {}).sort().forEach((k) => {
    if ((copy.strings[k].on || []).indexOf('app') >= 0) appStrings[k] = copy.strings[k].text;
  });
  const sinceJs = '// GENERATED by tools/widget_gen.js from workers/shared/since-rules.mjs and docs/widgets/widget-copy.json. Do not edit.\n'
    + '(function () {\n'
    + Object.keys(consts).map((k) => 'const ' + k + ' = ' + lit(consts[k]) + ';\n').join('')
    + moduleBody.replace(/\s*$/, '\n')
    + 'window.CubbySince = { ' + FN_NAMES.concat(['RULES', 'DEFAULTS', 'SNAPSHOT_VERSIONS']).join(', ') + ' };\n'
    + 'window.CubbyWidgetCopy = ' + lit(appStrings) + ';\n'
    + '})();\n';

  // The reference model's answer to every case, for the Swift and Kotlin goldens (plan 1 Task 5). The model formats
  // in UTC (getUTC*), so these bytes do not depend on the machine's zone; tz tells the natives which zone to use.
  const renderModel = createModel(copy, readQuickActions(root));
  const fixtures = {
    source: crypto.createHash('sha256').update(fs.readFileSync(path.join(root, 'docs/widgets/widget-copy.json'))).digest('hex'),
    tz: 'UTC',
    fixtures: (copy.cases || []).map((c) => ({ name: c.name, input: c.input, expect: renderModel(c.input) })),
    napCases: copy.napCases || [],
  };

  const native = generateNative(copy, readQuickActions(root));
  return Object.assign({
    'workers/shared/widget-rules.mjs': rulesMjs,
    'app/since-rules.js': sinceJs,
    'docs/widgets/widget-fixtures.json': lit(fixtures) + '\n',
  }, native);
}

/* ---- the native constants (plan 1 Task 6, roadmap 2.3) ------------------------------------------------------
 * Each platform's file holds only that platform's strings and actions, so iOS has no `voice` and no Android-only
 * key. Names drop the dots and capitalise the next letter (status.lastFeed -> statusLastFeed); Android resource
 * names are w_ plus snake case (w_status_last_feed). WColor/WColors, Swift WCopy.text(_:) and the intents block
 * are plan 3 Task 2's emitters, not here. */
const GEN_NOTE = 'GENERATED by tools/widget_gen.js from docs/widgets/widget-copy.json and app/index.html. Do not edit.';
const SWIFT_PATH = 'native-ios/CubbyWidget/Generated.swift';
const KOTLIN_PATH = 'native-android/app/src/main/java/com/littlecubby/app/widget/Generated.kt';
const XML_PATH = 'native-android/app/src/main/res/values/widget_strings.xml';
const camelName = (k) => k.split('.').map((p, i) => (i ? p[0].toUpperCase() + p.slice(1) : p)).join('');
const snakeName = (k) => 'w_' + k.split('.').join('_').replace(/([a-z0-9])([A-Z])/g, '$1_$2').toLowerCase();
function escSource(str, dollar) {
  let o = '';
  for (const ch of str) {
    const c = ch.codePointAt(0);
    if (ch === '\\') o += '\\\\';
    else if (ch === '"') o += '\\"';
    else if (ch === '\n') o += '\\n';
    else if (ch === '\t') o += '\\t';
    else if (dollar && ch === '$') o += '\\$';
    else if (c < 32 || c === 127) o += dollar ? '\\u' + ('0000' + c.toString(16)).slice(-4) : '\\u{' + c.toString(16) + '}';
    else o += ch;
  }
  return '"' + o + '"';
}
function escXml(str) {
  let o = str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/'/g, "\\'").replace(/"/g, '\\"');
  if (/^[@?]/.test(o)) o = '\\' + o;
  // aapt2 trims leading and trailing whitespace of an unquoted <string> BEFORE it reads escapes, so " and " would
  // ship as "and" and joined names would render "RobinandWren". An escaped \u0020 is not whitespace to the trim.
  // Chosen over wrapping in "..." because it leaves every other string and its apostrophe escapes byte-identical.
  o = o.replace(/^ +/, (m) => '\\u0020'.repeat(m.length)).replace(/ +$/, (m) => '\\u0020'.repeat(m.length));
  return o;
}
function generateNative(copy, actions) {
  const strings = copy.strings || {};
  const forPlatform = (pl) => Object.keys(strings).sort().filter((k) => (strings[k].platforms || []).indexOf(pl) >= 0);
  const actsFor = (pl) => actions.filter((a) => !a.platforms || a.platforms.indexOf(pl) >= 0);
  const seen = {};
  Object.keys(strings).forEach((k) => {   // two keys that fold to one Swift or Android name would silently shadow
    [camelName(k), snakeName(k)].forEach((n) => { if (seen[n] && seen[n] !== k) throw new Error('widget-copy keys ' + seen[n] + ' and ' + k + ' both generate the name ' + n); seen[n] = k; });
  });
  const rules = sortKeys(copy.rules), defaults = sortKeys(copy.defaults);
  const swiftValue = (v) => (typeof v === 'string' ? escSource(v) : Array.isArray(v) ? '[' + v.map(swiftValue).join(', ') + ']' : String(v));
  const kotlinValue = (v, num) => (typeof v === 'string' ? escSource(v, true) : Array.isArray(v) ? 'listOf(' + v.map((x) => kotlinValue(x)).join(', ') + ')' : num ? v + 'L' : String(v));
  const str = (a) => '[' + a.map((x) => escSource(x)).join(', ') + ']';

  const ik = forPlatform('ios');
  const swift = '// ' + GEN_NOTE + '\nimport Foundation\n\n'
    + 'enum WCopy {\n' + ik.map((k) => '    static let ' + camelName(k) + ' = ' + escSource(strings[k].text) + '\n').join('')
    + '    /// Replaces each {key} in s with its value.\n'
    + '    static func fill(_ s: String, _ args: [String: String]) -> String {\n'
    + '        var out = s\n        for (k, v) in args { out = out.replacingOccurrences(of: "{" + k + "}", with: v) }\n        return out\n    }\n}\n\n'
    + 'enum WRules {\n' + Object.keys(rules).map((k) => '    static let ' + k + ' = ' + swiftValue(rules[k]) + '\n').join('') + '}\n\n'
    + 'enum WDefaults {\n' + Object.keys(defaults).map((k) => '    static let ' + k + ' = ' + swiftValue(defaults[k]) + '\n').join('') + '}\n\n'
    + 'struct WAction {\n    let key: String\n    let go: String\n    let label: String\n    let inPlace: Bool\n    let perBaby: Bool\n    let places: [String]\n}\n\n'
    + 'enum WActions {\n    static let all: [WAction] = [\n'
    + actsFor('ios').map((a) => '        WAction(key: ' + escSource(a.key) + ', go: ' + escSource(a.go) + ', label: ' + escSource(a.label) + ', inPlace: ' + a.inPlace + ', perBaby: ' + a.perBaby + ', places: ' + str(a.places) + '),\n').join('')
    + '    ]\n}\n\n'
    + 'enum WSnapshot {\n    static let versions = ' + swiftValue(copy.snapshot.versions) + '\n}\n';

  const ak = forPlatform('android');
  const kotlin = '// ' + GEN_NOTE + '\npackage com.littlecubby.app.widget\n\nimport com.littlecubby.app.R\n\n'
    + 'object WCopy {\n' + ak.map((k) => '    val ' + camelName(k) + ': Int get() = R.string.' + snakeName(k) + '\n').join('')
    + '    val byKey: Map<String, Int> = mapOf(\n' + ak.map((k) => '        ' + escSource(k, true) + ' to R.string.' + snakeName(k) + ',\n').join('') + '    )\n'
    + '    /** Replaces each {key} in s with its value. */\n'
    + '    fun fill(s: String, args: Map<String, String>): String {\n'
    + '        var out = s\n        for ((k, v) in args) out = out.replace("{" + k + "}", v)\n        return out\n    }\n}\n\n'
    + 'object WRules {\n' + Object.keys(rules).map((k) => '    const val ' + k + ' = ' + kotlinValue(rules[k], true) + '\n').join('') + '}\n\n'
    + 'object WDefaults {\n' + Object.keys(defaults).map((k) => '    val ' + k + ' = ' + kotlinValue(defaults[k]) + '\n').join('') + '}\n\n'
    + 'data class WAction(\n    val key: String,\n    val go: String,\n    val label: String,\n    val inPlace: Boolean,\n    val perBaby: Boolean,\n    val places: List<String>,\n)\n\n'
    + 'object WActions {\n    val all: List<WAction> = listOf(\n'
    + actsFor('android').map((a) => '        WAction(' + escSource(a.key) + ', ' + escSource(a.go) + ', ' + escSource(a.label, true) + ', ' + a.inPlace + ', ' + a.perBaby + ', listOf(' + a.places.map((x) => escSource(x)).join(', ') + ')),\n').join('')
    + '    )\n}\n\n'
    + 'object WSnapshot {\n    val versions = ' + kotlinValue(copy.snapshot.versions) + '\n}\n';

  const xml = '<?xml version="1.0" encoding="utf-8"?>\n<!-- ' + GEN_NOTE + ' -->\n<resources>\n'
    + ak.map((k) => '    <string name="' + snakeName(k) + '">' + escXml(strings[k].text) + '</string>\n').join('') + '</resources>\n';
  return { [SWIFT_PATH]: swift, [KOTLIN_PATH]: kotlin, [XML_PATH]: xml };
}

/* The array between the WIDGET-QUICK-ACTIONS markers in app/index.html, evaluated in a vm so the arrow
 * functions in it are created and never called. Returns one row per action that carries a `widget` field. */
const QA_BEGIN = '/* WIDGET-QUICK-ACTIONS-BEGIN */';
const QA_END = '/* WIDGET-QUICK-ACTIONS-END */';
function readAllActions(root) {
  const html = fs.readFileSync(path.join(root, 'app/index.html'), 'utf8');
  const a = html.indexOf(QA_BEGIN), b = html.indexOf(QA_END);
  if (a < 0 || b < a) throw new Error('the QUICK_ACTIONS markers are missing from app/index.html');
  const chunk = html.slice(a + QA_BEGIN.length, b);
  const at = chunk.indexOf('const QUICK_ACTIONS=');
  if (at < 0) throw new Error('const QUICK_ACTIONS= is not between the markers');
  const arr = vm.runInNewContext('(' + chunk.slice(at + 'const QUICK_ACTIONS='.length).replace(/;\s*$/, '') + ')', {}, { timeout: 1000 });
  return arr.map((r) => ({ key: r.k, stages: r.s, label: r.label, widget: r.widget || null }));
}
function readQuickActions(root) {
  return readAllActions(root).filter((r) => r.widget).map((r) => ({
    key: r.key, go: r.widget.go, label: r.label, inPlace: !!r.widget.inPlace, perBaby: !!r.widget.perBaby,
    platforms: r.widget.platforms || null, places: r.widget.places.slice(),
  }));
}

module.exports = { generate, readQuickActions, readAllActions, camelName, snakeName };

if (require.main === module) {
  const root = path.join(__dirname, '..');
  const out = generate(root);
  if (process.argv.includes('--check')) {
    const bad = Object.keys(out).filter((p) => { try { return fs.readFileSync(path.join(root, p), 'utf8') !== out[p]; } catch (e) { return true; } });
    bad.forEach((p) => console.log('differs: ' + p));
    if (bad.length) { console.log('run: node tools/widget_gen.js'); process.exit(1); }
    console.log('widget_gen: generated files are current');
  } else {
    Object.keys(out).forEach((p) => { fs.mkdirSync(path.dirname(path.join(root, p)), { recursive: true }); fs.writeFileSync(path.join(root, p), out[p]); console.log('wrote ' + p); });
  }
}
